INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_06','V1014','陈会计',6,'我可以给你开具临时缴费凭证，窗口可凭凭证先受理你的材料。','wǒ kě yǐ gěi nǐ kāi jù lín shí jiǎo fèi píng zhèng， chuāng kǒu kě píng píng zhèng xiān shòu lǐ nǐ de cái liào。','Tôi có thể cấp cho anh một biên nhận thanh toán tạm thời, quầy tiếp nhận có thể dựa vào đó để tiếp nhận hồ sơ của anh trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_07','V1014','阮明',7,'太好了，那我现在立刻发送截图，麻烦您尽快核对处理。','tài hǎo le， nà wǒ xiàn zài lì kè fā sòng jié tú， má fán nín jǐn kuài hé duì chǔ lǐ。','Tuyệt quá, vậy tôi gửi ảnh chụp ngay bây giờ, phiền chị kiểm tra và xử lý sớm giúp tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_08','V1014','陈会计',8,'我今天下班前完成对账，要是资金仍未同步，你明天再来一趟。','wǒ jīn tiān xià bān qián wán chéng duì zhàng， yào shì zī jīn réng wèi tóng bù， nǐ míng tiān zài lái yī tàng。','Tôi sẽ hoàn tất đối soát trước khi hết giờ làm hôm nay, nếu tiền vẫn chưa được đồng bộ thì mai anh quay lại một chuyến nữa.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1015','SKC1','论文截止日前电脑硬盘崩溃文件丢失，找授课老师申请延期并借用图书馆设备',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1015','SIT1015','P1','twist','ban_chinh_thuc',NULL,'国内高校论文延期需提交书面说明+客观事故证明，任课老师无权私自延期，必须上报教务审批。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_01','V1015','阮明',1,'周老师，不好意思打扰您，我电脑硬盘突然损坏，整篇毕业论文全部丢失了啊。','zhōu lǎo shī， bù hǎo yì sī dǎ rǎo nín， wǒ diàn nǎo yìng pán tū rán sǔn huài， zhěng piān bì yè lùn wén quán bù diū shī le a。','Thầy Chu ơi, xin lỗi làm phiền thầy, ổ cứng máy tính của em đột nhiên hỏng, toàn bộ luận văn tốt nghiệp của em mất sạch rồi ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_02','V1015','周教授',2,'怎么会这么不巧？距离提交截止日期只剩明天中午了呢。','zěn me huì zhè me bù qiǎo？ jù lí tí jiāo jié zhǐ rì qī zhǐ shèng míng tiān zhōng wǔ le ne。','Sao lại xui xẻo đến vậy? Còn có đến trưa mai là hết hạn nộp bài rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_03','V1015','阮明',3,'我没有备份文件，硬盘完全读不出来，维修店说很难恢复数据。','wǒ méi yǒu bèi fèn wén jiàn， yìng pán wán quán dú bù chū lái， wéi xiū diàn shuō hěn nán huī fù shù jù。','Em không sao lưu file, ổ cứng giờ hoàn toàn không đọc được nữa, tiệm sửa chữa bảo rất khó khôi phục dữ liệu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_04','V1015','周教授',4,'我理解你的突发状况，但学院统一截止时间不能随便延后，流程很严格。','wǒ lǐ jiě nǐ de tū fā zhuàng kuàng， dàn xué yuàn tǒng yī jié zhǐ shí jiān bù néng suí biàn yán hòu， liú chéng hěn yán gé。','Thầy hiểu tình huống bất ngờ của em, nhưng thời hạn chung của khoa không thể tùy tiện lùi lại được, quy trình rất nghiêm ngặt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_05','V1015','阮明',5,'我能不能申请三天延期？图书馆有备用电脑，我可以连夜重新写完初稿。','wǒ néng bù néng shēn qǐng sān tiān yán qī？ tú shū guǎn yǒu bèi yòng diàn nǎo， wǒ kě yǐ lián yè chóng xīn xiě wán chū gǎo。','Em có thể xin gia hạn ba ngày được không ạ? Thư viện có máy tính dự phòng, em có thể thức đêm viết lại bản nháp cho xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_06','V1015','周教授',6,'你先写一份书面情况说明，附上电脑维修单据，我帮你向学院教务报备。','nǐ xiān xiě yī fèn shū miàn qíng kuàng shuō míng， fù shàng diàn nǎo wéi xiū dān jù， wǒ bāng nǐ xiàng xué yuàn jiào wù bào bèi。','Em viết một bản tường trình bằng văn bản trước đã, kèm theo hóa đơn sửa máy tính, thầy sẽ giúp em báo cáo lên phòng đào tạo của khoa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_07','V1015','阮明',7,'太感谢老师了，我现在就去图书馆借设备，通宵赶写论文。','tài gǎn xiè lǎo shī le， wǒ xiàn zài jiù qù tú shū guǎn jiè shè bèi， tōng xiāo gǎn xiě lùn wén。','Em cảm ơn thầy nhiều lắm, em đi thư viện mượn thiết bị ngay bây giờ, thức trắng đêm viết luận văn cho kịp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_08','V1015','周教授',8,'尽力加快进度，教务那边最多只能批准三天缓冲期，别再拖延啦。','jìn lì jiā kuài jìn dù， jiào wù nà biān zuì duō zhǐ néng pī zhǔn sān tiān huǎn chōng qī， bié zài tuō yán la。','Em cố gắng đẩy nhanh tiến độ nhé, bên phòng đào tạo nhiều nhất cũng chỉ có thể duyệt cho ba ngày gia hạn thôi, đừng trì hoãn thêm nữa đấy.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1016','SKC1','出入境预约号当日失效，携带齐全材料现场窗口申请加急受理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1016','SIT1016','P1','that_bai_nhe','ban_chinh_thuc',NULL,'出入境线上预约实行分时段限号制度，普通出行、学术活动不纳入紧急加急受理范围，仅重大医疗、亲属变故可走绿色通道。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_01','V1016','阮明',1,'你好，我线上预约的今天办理签证续签，预约号显示失效了，材料全都带齐了。','nǐ hǎo， wǒ xiàn shàng yù yuē de jīn tiān bàn lǐ qiān zhèng xù qiān， yù yuē hào xiǎn shì shī xiào le， cái liào quán dōu dài qí le。','Chào chị, em đặt lịch hẹn online để làm gia hạn visa hôm nay, nhưng mã đặt lịch lại báo hết hiệu lực, trong khi giấy tờ em đã mang đầy đủ hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_02','V1016','小徐',2,'预约号过期只能重新线上预约，线下窗口不接受无号业务办理哦。','yù yuē hào guò qī zhǐ néng chóng xīn xiàn shàng yù yuē， xiàn xià chuāng kǒu bù jiē shòu wú hào yè wù bàn lǐ ó。','Mã đặt lịch hết hạn thì chỉ có thể đặt lại online thôi, quầy trực tiếp không tiếp nhận trường hợp không có mã đâu.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_03','V1016','阮明',3,'我下周就要离校出差，根本没时间重新预约，能不能通融一下加急处理呢？','wǒ xià zhōu jiù yào lí xiào chū chāi， gēn běn méi shí jiān chóng xīn yù yuē， néng bù néng tōng róng yī xià jiā jí chǔ lǐ ne？','Tuần sau em đã phải rời trường đi công tác rồi, thật sự không có thời gian đặt lại lịch, chị có thể linh động xử lý gấp giúp em được không ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_04','V1016','小徐',4,'加急业务仅限紧急就医、亲属病危这类特殊情况，出行出差不符合加急标准。','jiā jí yè wù jǐn xiàn jǐn jí jiù yī、 qīn shǔ bìng wēi zhè lèi tè shū qíng kuàng， chū xíng chū chāi bù fú hé jiā jí biāo zhǔn。','Xử lý khẩn cấp chỉ áp dụng cho các trường hợp đặc biệt như cấp cứu y tế, người thân nguy kịch, còn đi công tác thì không đủ tiêu chuẩn để xử lý gấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_05','V1016','阮明',5,'我是留学生，外出参加国际学术会议，会议邀请函我随身带来了啊。','wǒ shì liú xué shēng， wài chū cān jiā guó jì xué shù huì yì， huì yì yāo qǐng hán wǒ suí shēn dài lái le a。','Em là du học sinh, em đi dự hội nghị học thuật quốc tế, thư mời tham dự hội nghị em cũng mang theo người đây này.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_06','V1016','小徐',6,'我帮你咨询窗口主管，你先在这里等候几分钟，不要离开。','wǒ bāng nǐ zī xún chuāng kǒu zhǔ guǎn， nǐ xiān zài zhè lǐ děng hòu jǐ fēn zhōng， bú yào lí kāi。','Để chị hỏi giúp em phụ trách quầy, em cứ đợi ở đây vài phút, đừng đi đâu nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_07','V1016','阮明',7,'麻烦你多帮忙说说，错过会议对我的学业影响很大。','má fán nǐ duō bāng máng shuō shuō， cuò guò huì yì duì wǒ de xué yè yǐng xiǎng hěn dà。','Phiền chị nói giúp em thêm chút nữa, nếu lỡ mất hội nghị này sẽ ảnh hưởng rất lớn đến việc học của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_08','V1016','小徐',8,'主管回复了，依旧无法现场受理，只能明天重新抢预约号。','zhǔ guǎn huí fù le， yī jiù wú fǎ xiàn chǎng shòu lǐ， zhǐ néng míng tiān chóng xīn qiǎng yù yuē hào。','Phụ trách đã phản hồi rồi, vẫn không thể tiếp nhận tại chỗ được, chỉ có thể để mai em đặt lại mã hẹn thôi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1017','SKC1','诈骗来电谎称家人重病要求汇款，冷静核实后联系学院反诈老师',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1017','SIT1017','P1','suon_se','ban_chinh_thuc',NULL,'国内高校会定期开展留学生反诈宣讲，遭遇疑似诈骗可直接联系国际学院辅导员，同步上报公安反诈平台。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_01','V1017','阮明',1,'郑老师，我刚刚接到一通陌生电话，说我母亲重病住院，急需我立刻转账过去。','zhèng lǎo shī， wǒ gāng gāng jiē dào yí tòng mò shēng diàn huà， shuō wǒ mǔ qīn zhòng bìng zhù yuàn， jí xū wǒ lì kè zhuǎn zhàng guò qù。','Cô Trịnh, em vừa nhận được một cuộc gọi lạ, họ nói mẹ em bị bệnh nặng nhập viện, cần em chuyển tiền gấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_02','V1017','郑老师',2,'你先别慌，有没有第一时间通过视频电话联系家里确认情况？','nǐ xiān bié huāng， yǒu méi yǒu dì yī shí jiān tōng guò shì pín diàn huà lián xì jiā lǐ què rèn qíng kuàng？','Em bình tĩnh đã, có gọi video về nhà xác nhận tình hình ngay chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_03','V1017','阮明',3,'我马上打视频给我妈妈，她身体好好的，根本没有生病这回事呢。','wǒ mǎ shàng dǎ shì pín gěi wǒ mā mā， tā shēn tǐ hǎo hǎo de， gēn běn méi yǒu shēng bìng zhè huí shì ne。','Em gọi video cho mẹ ngay, mẹ khỏe re à, chẳng có chuyện bị bệnh gì cả đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_04','V1017','郑老师',4,'这是典型跨境冒充亲属诈骗，很多留学生都接到过同类来电。','zhè shì diǎn xíng kuà jìng mào chōng qīn shǔ zhà piàn， hěn duō liú xué shēng dōu jiē dào guò tóng lèi lái diàn。','Đây là kiểu lừa đảo giả mạo người thân xuyên biên giới điển hình, nhiều du học sinh cũng từng gặp cuộc gọi tương tự rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_05','V1017','阮明',5,'骗子还准确说出我的姓名和家乡信息，差点我就准备转账了，太吓人啦。','piàn zi hái zhǔn què shuō chū wǒ de xìng míng hé jiā xiāng xìn xī， chà diǎn wǒ jiù zhǔn bèi zhuǎn zhàng le， tài xià rén la。','Kẻ lừa đảo còn nói đúng tên em và thông tin quê nhà, suýt chút nữa em đã chuyển tiền, sợ thật đó.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_06','V1017','郑老师',6,'把对方的来电号码发给我，学院统一上报反诈中心备案拦截。','bǎ duì fāng de lái diàn hào mǎ fā gěi wǒ， xué yuàn tǒng yī shàng bào fǎn zhà zhōng xīn bèi àn lán jié。','Em gửi số điện thoại của người đó cho cô, học viện sẽ báo lên trung tâm phòng chống lừa đảo để chặn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_07','V1017','阮明',7,'好，我现在转发号码，之后再有陌生要钱电话我都会先来问您。','hǎo， wǒ xiàn zài zhuǎn fā hào mǎ， zhī hòu zài yǒu mò shēng yào qián diàn huà wǒ dōu huì xiān lái wèn nín。','Vâng, em gửi số ngay đây, sau này có cuộc gọi lạ hỏi tiền em sẽ hỏi cô trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_08','V1017','郑老师',8,'记住，凡是催你立刻转账的陌生来电，一律不要相信，先核实家人。','jì zhù， fán shì cuī nǐ lì kè zhuǎn zhàng de mò shēng lái diàn， yī lǜ bú yào xiāng xìn， xiān hé shí jiā rén。','Nhớ nhé, hễ cuộc gọi lạ nào thúc em chuyển tiền ngay thì tuyệt đối không tin, phải xác nhận với gia đình trước.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1018','SKC1','校园学习账号被盗用登录，联系学校信息中心紧急冻结账号',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1018','SIT1018','P1','twist','ban_chinh_thuc',NULL,'国内高校校园账号绑定学籍、选课、图书馆借阅权限，被盗用可能泄露个人学籍信息，必须线下核验身份永久冻结。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_01','V1018','阮明',1,'您好，我的校园学习平台账号异地登录，应该是被盗用了，麻烦帮忙冻结账号吧。','nín hǎo， wǒ de xiào yuán xué xí píng tái zhàng hào yì dì dēng lù， yīng gāi shì bèi dào yòng le， má fán bāng máng dòng jié zhàng hào ba。','Chào anh, tài khoản học tập trên hệ thống của trường em bị đăng nhập từ nơi khác, hình như bị đánh cắp rồi, làm ơn giúp em khóa tài khoản lại.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_02','V1018','小高',2,'请提供你的学号、实名姓名，我先查询账号登录记录看看。','qǐng tí gōng nǐ de xué hào、 shí míng xìng míng， wǒ xiān chá xún zhàng hào dēng lù jì lù kàn kàn。','Em cho anh mã số sinh viên và họ tên thật, anh kiểm tra lịch sử đăng nhập tài khoản trước xem sao.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_03','V1018','阮明',3,'学号20230418，姓名阮明，系统提示今早凌晨在外地设备登录啊。','xué hào 20230418， xìng míng ruǎn míng， xì tǒng tí shì jīn zǎo líng chén zài wài dì shè bèi dēng lù a。','Mã số sinh viên là 20230418, tên là Nguyễn Minh, hệ thống báo sáng nay có thiết bị ở nơi khác đăng nhập lúc rạng sáng đó.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_04','V1018','小高',4,'账号冻结需要核验身份，你要携带学生证线下到机房办理完整锁定手续。','zhàng hào dòng jié xū yào hé yàn shēn fèn， nǐ yào xié dài xué shēng zhèng xiàn xià dào jī fáng bàn lǐ wán zhěng suǒ dìng shǒu xù。','Để khóa tài khoản thì cần xác minh danh tính, em phải mang thẻ sinh viên xuống phòng máy làm thủ tục khóa đầy đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_05','V1018','阮明',5,'我现在在教学楼上课走不开，能不能线上临时冻结，等下课再去机房？','wǒ xiàn zài zài jiào xué lóu shàng kè zǒu bù kāi， néng bù néng xiàn shàng lín shí dòng jié， děng xià kè zài qù jī fáng？','Em đang học trên giảng đường không đi được, có thể tạm khóa online trước, đợi hết giờ học em xuống phòng máy được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_06','V1018','小高',6,'我可以先临时限制登录两小时，超时会自动解除，线下才能永久锁定。','wǒ kě yǐ xiān lín shí xiàn zhì dēng lù liǎng xiǎo shí， chāo shí huì zì dòng jiě chú， xiàn xià cái néng yǒng jiǔ suǒ dìng。','Anh có thể tạm hạn chế đăng nhập trong hai giờ trước, hết thời gian sẽ tự mở lại, muốn khóa vĩnh viễn thì phải làm trực tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_07','V1018','阮明',7,'两小时足够我下课过去，麻烦您现在先帮我临时锁上账号。','liǎng xiǎo shí zú gòu wǒ xià kè guò qù， má fán nín xiàn zài xiān bāng wǒ lín shí suǒ shàng zhàng hào。','Hai giờ là đủ để em đi xuống sau khi học xong rồi, nhờ anh tạm khóa tài khoản giúp em ngay bây giờ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_08','V1018','小高',8,'已经临时限制登录了，尽快带证件过来重置密码完善安全验证。','yǐ jīng lín shí xiàn zhì dēng lù le， jǐn kuài dài zhèng jiàn guò lái zhòng zhì mì mǎ wán shàn ān quán yàn zhèng。','Anh đã tạm hạn chế đăng nhập rồi, em nhanh mang giấy tờ xuống đặt lại mật khẩu và hoàn thiện xác minh an ninh.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1019','SKC1','社交平台私人照片被恶意转发骚扰，到学校保卫处寻求介入处理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1019','SIT1019','P1','suon_se','chinh_thuc',NULL,'个人肖像被恶意转发骚扰属于侵权行为，学校保卫处可出具证明协助学生向社交平台申请删除内容、封禁侵权账号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_01','V1019','阮明',1,'李干事您好，有人保存我的私人生活照片，转发到社交平台私信骚扰我。','lǐ gàn shì nín hǎo， yǒu rén bǎo cún wǒ de sī rén shēng huó zhào piàn， zhuǎn fā dào shè jiāo píng tái sī xìn sāo rǎo wǒ。','Chào anh Lý, có người lưu lại ảnh sinh hoạt cá nhân của em rồi phát lên mạng xã hội để nhắn tin quấy rối em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_02','V1019','李干事',2,'你先把对方骚扰截图、转发照片的完整记录全部截图保存好。','nǐ xiān bǎ duì fāng sāo rǎo jié tú、 zhuǎn fā zhào piān de wán zhěng jì lù quán bù jié tú bǎo cún hǎo。','Em chụp lại và lưu đầy đủ toàn bộ tin nhắn quấy rối và những ảnh bị phát tán đó lại nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_03','V1019','阮明',3,'所有聊天记录我都存好了，对方是校外人员，我不知道对方真实身份呢。','suǒ yǒu liáo tiān jì lù wǒ dōu cún hǎo le， duì fāng shì xiào wài rén yuán， wǒ bù zhī dào duì fāng zhēn shí shēn fèn ne。','Toàn bộ tin nhắn em đã lưu hết rồi, người đó là người ngoài trường, em không biết danh tính thật của họ ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_04','V1019','李干事',4,'我们会出具学校证明，协助你联系平台客服调取对方注册信息。','wǒ men huì chū jù xué xiào zhèng míng， xié zhù nǐ lián xì píng tái kè fú diào qǔ duì fāng zhù cè xìn xī。','Trường sẽ cấp giấy xác nhận, hỗ trợ em liên hệ bên chăm sóc khách hàng của nền tảng để truy xuất thông tin đăng ký của người đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_05','V1019','阮明',5,'对方持续发消息骚扰，严重影响我上课和休息，希望尽快制止。','duì fāng chí xù fā xiāo xī sāo rǎo， yán zhòng yǐng xiǎng wǒ shàng kè hé xiū xī， xī wàng jǐn kuài zhì zhǐ。','Người đó liên tục gửi tin nhắn quấy rối, ảnh hưởng nghiêm trọng đến việc học và nghỉ ngơi của em, mong sớm được ngăn chặn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_06','V1019','李干事',6,'我先登记你的情况，今天就发函给平台要求下架相关照片。','wǒ xiān dēng jì nǐ de qíng kuàng， jīn tiān jiù fā hán gěi píng tái yāo qiú xià jià xiāng guān zhào piān。','Tôi sẽ ghi nhận trường hợp của em, ngay hôm nay sẽ gửi văn bản yêu cầu nền tảng gỡ những ảnh đó xuống.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_07','V1019','阮明',7,'太感谢您了，我之前不知道学校保卫处可以处理网络骚扰问题。','tài gǎn xiè nín le， wǒ zhī qián bù zhī dào xué xiào bǎo wèi chù kě yǐ chǔ lǐ wǎng luò sāo rǎo wèn tí。','Em cảm ơn anh nhiều lắm, trước đây em không biết phòng bảo vệ của trường cũng xử lý được vấn đề quấy rối trên mạng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_08','V1019','李干事',8,'校内师生遭遇网络侵权、骚扰都可以来报备，我们会配合平台维权。','xiào nèi shī shēng zāo yù wǎng luò qīn quán、 sāo rǎo dōu kě yǐ lái bào bèi， wǒ men huì pèi hé píng tái wéi quán。','Thầy cô, sinh viên trong trường gặp phải xâm phạm quyền lợi hay quấy rối trên mạng đều có thể đến báo cáo, chúng tôi sẽ phối hợp với nền tảng để bảo vệ quyền lợi cho các em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1020','SKC1','社团活动现场两名同学激烈争吵，上前劝解并通知社团负责人',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1020','SIT1020','P1','twist','tuy_y',NULL,'国内校园社团公共场合发生争吵会影响社团评优，负责人一般会分开双方私下调解，避免当众激化矛盾。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_01','V1020','阮明',1,'小宇，你快过来一下，策划部两位同学吵得特别凶，谁都不肯让步啊。','xiǎo yǔ， nǐ kuài guò lái yī xià， cè huà bù liǎng wèi tóng xué chǎo dé tè bié xiōng， shéi dōu bù kěn ràng bù a。','Tiểu Vũ, ra đây nhanh đi, hai bạn ở ban tổ chức đang cãi nhau dữ lắm, ai cũng không chịu nhường ai kìa.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_02','V1020','小宇',2,'怎么回事？活动现场还有这么多新生，吵起来影响太不好了吧。','zěn me huí shì？ huó dòng xiàn chǎng hái yǒu zhè me duō xīn shēng， chǎo qǐ lái yǐng xiǎng tài bù hǎo le ba。','Sao vậy? Sự kiện còn nhiều sinh viên mới ở đây mà cãi nhau thì ảnh hưởng không hay đâu.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_03','V1020','阮明',3,'两人对活动预算分配意见不合，声音越来越大，周围同学都在围观。','liǎng rén duì huó dòng yù suàn fēn pèi yì jiàn bù hé， shēng yīn yuè lái yuè dà， zhōu wéi tóng xué dōu zài wéi guān。','Hai người bất đồng về cách phân bổ ngân sách hoạt động, giọng càng lúc càng lớn, các bạn xung quanh đứng xem đông luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_04','V1020','小宇',4,'你先把两人分开，分别带到两边休息室，别在大厅当众争执。','nǐ xiān bǎ liǎng rén fēn kāi， fēn bié dài dào liǎng biān xiū xī shì， bié zài dà tīng dāng zhòng zhēng zhí。','Em tách hai người ra trước, dẫn từng người sang phòng nghỉ hai bên, đừng để họ cãi nhau công khai ở đại sảnh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_05','V1020','阮明',5,'我劝了半天，两人情绪都很激动，根本不愿意冷静沟通呢。','wǒ quàn le bàn tiān， liǎng rén qíng xù dōu hěn jī dòng， gēn běn bù yuàn yì lěng jìng gōu tōng ne。','Em khuyên mãi rồi mà cả hai đều đang nóng, chẳng ai chịu bình tĩnh nói chuyện cả.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_06','V1020','小宇',6,'我现在过去单独跟他们谈话，你帮忙安抚一下围观的新生。','wǒ xiàn zài guò qù dān dú gēn tā men tán huà， nǐ bāng máng ān fǔ yī xià wéi guān de xīn shēng。','Giờ anh qua nói chuyện riêng với từng người, em giúp anh trấn an mấy bạn đang đứng xem nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_07','V1020','阮明',7,'没问题，我先转移大家注意力，避免场面变得更尴尬。','méi wèn tí， wǒ xiān zhuǎn yí dà jiā zhù yì lì， bì miǎn chǎng miàn biàn dé gèng gān gà。','Không vấn đề gì, em sẽ hướng sự chú ý của mọi người đi chỗ khác trước, tránh để tình huống thêm khó xử.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_08','V1020','小宇',8,'辛苦你了，社团有矛盾及时告诉我，别任由冲突发酵。','xīn kǔ nǐ le， shè tuán yǒu máo dùn jí shí gào sù wǒ， bié rèn yóu chōng tū fā jiào。','Cảm ơn em nhiều, câu lạc bộ có mâu thuẫn thì báo anh kịp thời, đừng để xung đột âm ỉ leo thang.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1021','SKC1','自习室同学突发癫痫，疏散人群、联系校医、维持现场秩序',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1021','SIT1021','P1','suon_se','ban_chinh_thuc',NULL,'国内校园普及癫痫急救基础常识，发病时禁止强行束缚患者肢体，保持通风、清理周边硬物是基础急救方式。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_01','V1021','阮明',1,'思琪学姐，这边有位同学突然倒地抽搐，像是癫痫发作了！','sī qí xué jiě， zhè biān yǒu wèi tóng xué tū rán dǎo dì chōu chù， xiàng shì diān xián fā zuò le！','Chị Tư Kỳ, ở đây có một bạn tự nhiên ngã lăn xuống co giật, giống như bị động kinh vậy!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_02','V1021','思琪',2,'大家先不要围过来，全部后退留出通风空间，别挤在这里啊。','dà jiā xiān bú yào wéi guò lái， quán bù hòu tuì liú chū tōng fēng kōng jiān， bié jǐ zài zhè lǐ a。','Mọi người đừng xúm lại gần, lùi ra hết để chỗ thoáng, đừng chen chúc ở đây nhé.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_03','V1021','阮明',3,'我已经把周围桌椅挪开，避免他磕碰受伤，现在要立刻联系校医吧？','wǒ yǐ jīng bǎ zhōu wéi zhuō yǐ nuó kāi， bì miǎn tā kē pèng shòu shāng， xiàn zài yào lì kè lián xì xiào yī ba？','Em đã dời bàn ghế xung quanh ra rồi để bạn không va vào bị thương, giờ phải gọi bác sĩ trường ngay đúng không chị?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_04','V1021','思琪',4,'我马上拨打校医应急电话，你帮忙拿一件外套垫在他头下面。','wǒ mǎ shàng bō dǎ xiào yī yìng jí diàn huà， nǐ bāng máng ná yī jiàn wài tào diàn zài tā tóu xià miàn。','Chị gọi ngay số cấp cứu của y tế trường, em lấy giúp một cái áo lót dưới đầu bạn đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_05','V1021','阮明',5,'好，我按住他身边的桌椅，防止抽搐时撞到边角，现在意识不清醒呢。','hǎo， wǒ àn zhù tā shēn biān de zhuō yǐ， fáng zhǐ chōu chù shí zhuàng dào biān jiǎo， xiàn zài yì shí bù qīng xǐng ne。','Vâng, em đang giữ bàn ghế bên cạnh bạn để tránh lúc co giật va vào góc cạnh, giờ bạn đang mất ý thức rồi.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_06','V1021','思琪',6,'不要强行按压他的四肢，等校医过来再做专业处理，大家安静一点。','bú yào qiáng xíng àn yā tā de sì zhī， děng xiào yī guò lái zài zuò zhuān yè chǔ lǐ， dà jiā ān jìng yì diǎn。','Đừng cố giữ chặt tay chân bạn ấy, để bác sĩ trường tới xử lý chuyên môn, mọi người trật tự một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_07','V1021','阮明',7,'我会维持秩序，不让围观同学上前触碰，等待医护人员到场。','wǒ huì wéi chí zhì xù， bù ràng wéi guān tóng xué shàng qián chù pèng， děng dài yī hù rén yuán dào chǎng。','Em sẽ giữ trật tự, không cho các bạn đứng xem lại gần đụng vào, chờ nhân viên y tế tới.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_08','V1021','思琪',8,'多亏你及时发现，慌乱围观很容易给发病同学造成二次伤害。','duō kuī nǐ jí shí fā xiàn， huāng luàn wéi guān hěn róng yì gěi fā bìng tóng xué zào chéng èr cì shāng hài。','May mà em phát hiện kịp, mọi người xúm lại xem trong lúc hoảng loạn rất dễ gây thêm tổn thương cho bạn đang lên cơn.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1022','SKC1','校外租房房东私自换锁不让进门，拨打社区民警协调房屋纠纷',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1022','SIT1022','P1','that_bai_nhe','chinh_thuc',NULL,'租房纠纷属于民事纠纷，民警仅负责现场调解，无权强制破门，双方无法达成一致需走法院民事诉讼。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_01','V1022','阮明',1,'王警官您好，我租的房子房东私自更换门锁，不让我进屋拿个人物品。','wáng jǐng guān nín hǎo， wǒ zū de fáng zi fáng dōng sī zì gēng huàn mén suǒ， bù ràng wǒ jìn wū ná gè rén wù pǐn。','Chào chú Vương, nhà em thuê nhưng chủ nhà tự ý đổi khóa, không cho em vào lấy đồ cá nhân.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_02','V1022','王民警',2,'出示你的租房合同、身份证件，跟我说清楚房东换锁的原因吧。','chū shì nǐ de zū fáng hé tóng、 shēn fèn zhèng jiàn， gēn wǒ shuō qīng chǔ fáng dōng huàn suǒ de yuán yīn ba。','Em đưa hợp đồng thuê nhà, giấy tờ tùy thân ra, nói rõ cho chú nguyên nhân chủ nhà đổi khóa xem sao.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_03','V1022','阮明',3,'房租我按时足额缴纳，房东单方面想涨租，我没同意就直接换锁了啊。','fáng zū wǒ àn shí zú é jiǎo nà， fáng dōng dān fāng miàn xiǎng zhǎng zū， wǒ méi tóng yì jiù zhí jiē huàn suǒ le a。','Em đóng tiền thuê đúng hạn đủ số, chủ nhà đơn phương muốn tăng tiền thuê, em không đồng ý là họ đổi khóa luôn ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_04','V1022','王民警',4,'私自换锁扣押租客私人物品属于违规，我现在联系房东到场调解。','sī zì huàn suǒ kòu yā zū kè sī rén wù pǐn shǔ yú wéi guī， wǒ xiàn zài lián xì fáng dōng dào chǎng tiáo jiě。','Tự ý đổi khóa giữ đồ cá nhân của người thuê là vi phạm, chú sẽ liên hệ chủ nhà tới đây để hòa giải ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_05','V1022','阮明',5,'我的电脑、居留卡全都放在屋内，今晚没地方住，能不能先进屋拿东西？','wǒ de diàn nǎo、 jū liú kǎ quán dōu fàng zài wū nèi， jīn wǎn méi dì fāng zhù， néng bù néng xiān jìn wū ná dōng xī？','Máy tính, thẻ tạm trú của em đều để trong nhà, tối nay không có chỗ ở, chú cho em vào lấy đồ trước được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_06','V1022','王民警',6,'调解需要双方到场，房东半小时后才能过来，暂时无法开门。','tiáo jiě xū yào shuāng fāng dào chǎng， fáng dōng bàn xiǎo shí hòu cái néng guò lái， zàn shí wú fǎ kāi mén。','Hòa giải cần có mặt cả hai bên, chủ nhà nửa giờ nữa mới tới được, tạm thời chưa mở cửa được đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_07','V1022','阮明',7,'那我今晚只能临时住酒店，贵重证件都在房间里，实在不放心。','nà wǒ jīn wǎn zhǐ néng lín shí zhù jiǔ diàn， guì zhòng zhèng jiàn dōu zài fáng jiān lǐ， shí zài bù fàng xīn。','Vậy tối nay em đành tạm ở khách sạn, giấy tờ quan trọng đều ở trong phòng, em thật sự không an tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_08','V1022','王民警',8,'我全程在场调解，等房东到场后优先让你取出随身重要证件。','wǒ quán chéng zài chǎng tiáo jiě， děng fáng dōng dào chǎng hòu yōu xiān ràng nǐ qǔ chū suí shēn zhòng yào zhèng jiàn。','Chú sẽ có mặt hòa giải từ đầu đến cuối, đợi chủ nhà tới sẽ ưu tiên cho em lấy giấy tờ quan trọng mang theo trước.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1023','SKC1','校医院无法处理急症，拨打120同时同步告知国际学院辅导员',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1023','SIT1023','P1','suon_se','ban_chinh_thuc',NULL,'国内高校校医院仅处理轻症，重症统一转送综合医院，留学生可凭留学生医保报销部分急诊费用。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_01','V1023','阮明',1,'李导，我现在在校医院，医生说我的急症这里处理不了，已经拨打120送综合医院了。','lǐ dǎo， wǒ xiàn zài zài xiào yī yuàn， yī shēng shuō wǒ de jí zhèng zhè lǐ chǔ lǐ bù liǎo， yǐ jīng bō dǎ 120 sòng zōng hé yī yuàn le。','Anh Lý, em đang ở bệnh viện trường, bác sĩ nói bệnh cấp cứu của em ở đây không xử lý được, em đã gọi 120 để chuyển đến bệnh viện tổng hợp rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_02','V1023','李辅导员',2,'是什么急症？救护车大概多久能到达校门口呢？','shì shén me jí zhèng？ jiù hù chē dà gài duō jiǔ néng dào dá xiào mén kǒu ne？','Bệnh cấp cứu gì vậy? Xe cứu thương khoảng bao lâu nữa tới được cổng trường?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_03','V1023','阮明',3,'急性肠胃炎伴随剧烈脱水，校医院缺少输液设备，救护车十分钟就到啦。','jí xìng cháng wèi yán bàn suí jù liè tuō shuǐ， xiào yī yuàn quē shǎo shū yè shè bèi， jiù hù chē shí fēn zhōng jiù dào la。','Viêm dạ dày ruột cấp kèm mất nước nặng, bệnh viện trường thiếu thiết bị truyền dịch, xe cứu thương mười phút nữa tới rồi ạ.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_04','V1023','李辅导员',4,'我现在登记你的情况，等下会跟急诊医院说明你留学生身份。','wǒ xiàn zài dēng jì nǐ de qíng kuàng， děng xià huì gēn jí zhěn yī yuàn shuō míng nǐ liú xué shēng shēn fèn。','Anh ghi nhận tình hình của em ngay, chút nữa sẽ báo với bệnh viện cấp cứu là em là du học sinh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_05','V1023','阮明',5,'我一个人等救护车，居留卡、学生证都随身带着，方便登记就诊。','wǒ yí gè rén děng jiù hù chē， jū liú kǎ、 xué shēng zhèng dōu suí shēn dài zhe， fāng biàn dēng jì jiù zhěn。','Em đang chờ xe cứu thương một mình, thẻ tạm trú và thẻ sinh viên em đều mang theo, tiện cho việc đăng ký khám.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_06','V1023','李辅导员',6,'我处理完手头工作就赶去医院，有任何不舒服随时给我打电话。','wǒ chǔ lǐ wán shǒu tóu gōng zuò jiù gǎn qù yī yuàn， yǒu rèn hé bù shū fú suí shí gěi wǒ dǎ diàn huà。','Anh xử lý xong việc đang làm sẽ tới bệnh viện ngay, có gì khó chịu thì gọi anh bất cứ lúc nào nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_07','V1023','阮明',7,'好，麻烦您了，就医缴费相关流程我不太清楚，到时候还要请教您。','hǎo， má fán nín le， jiù yī jiǎo fèi xiāng guān liú chéng wǒ bù tài qīng chǔ， dào shí hòu hái yào qǐng jiào nín。','Vâng, cảm ơn anh nhiều, quy trình khám và đóng viện phí em chưa rõ lắm, lúc đó phải hỏi anh thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_08','V1023','李辅导员',8,'放心，留学生医保报销材料我之后会发给你，安心就医就好。','fàng xīn， liú xué shēng yī bǎo bào xiāo cái liào wǒ zhī hòu huì fā gěi nǐ， ān xīn jiù yī jiù hǎo。','Yên tâm, giấy tờ bảo hiểm y tế để hoàn tiền cho du học sinh anh sẽ gửi cho em sau, cứ yên tâm khám bệnh đi.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1024','SKC1','异地就医刷卡银行卡被风控冻结，紧急致电银行客服解锁',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1024','SIT1024','P1','twist','chinh_thuc',NULL,'国内银行卡异地大额消费易触发风控冻结，线上临时解锁额度有限，大额资金解冻必须线下网点核验身份。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_01','V1024','阮明',1,'您好，我现在在外地医院缴费，银行卡刷卡提示账户被风控冻结，急需解锁。','nín hǎo， wǒ xiàn zài zài wài dì yī yuàn jiǎo fèi， yín háng kǎ shuā kǎ tí shì zhàng hù bèi fēng kòng dòng jié， jí xū jiě suǒ。','Chào anh/chị, em đang ở bệnh viện tỉnh khác để đóng tiền, thẻ ngân hàng quẹt bị báo tài khoản bị kiểm soát rủi ro đóng băng, em cần mở khóa gấp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_02','V1024','客服',2,'请核实你的银行卡号、预留手机号、身份证/居留证件后四位。','qǐng hé shí nǐ de yín háng kǎ hào、 yù liú shǒu jī hào、 shēn fèn zhèng / jū liú zhèng jiàn hòu sì wèi。','Anh/chị vui lòng xác nhận số thẻ ngân hàng, số điện thoại đăng ký, và bốn số cuối của giấy tờ tùy thân/thẻ tạm trú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_03','V1024','阮明',3,'卡号6217开头，预留手机号138XXXX2741，证件后四位3152，现在要付医药费啊。','kǎ hào 6217 kāi tóu， yù liú shǒu jī hào 138XXXX2741， zhèng jiàn hòu sì wèi 3152， xiàn zài yào fù yī yào fèi a。','Số thẻ bắt đầu bằng 6217, số điện thoại đăng ký là 138XXXX2741, bốn số cuối giấy tờ là 3152, giờ em cần đóng tiền thuốc gấp ạ.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_04','V1024','客服',4,'系统检测到异地大额消费，自动触发风控保护，线上临时解锁有每日限额。','xì tǒng jiǎn cè dào yì dì dà é xiāo fèi， zì dòng chù fā fēng kòng bǎo hù， xiàn shàng lín shí jiě suǒ yǒu měi rì xiàn é。','Hệ thống phát hiện chi tiêu số tiền lớn ở khu vực khác, tự động kích hoạt bảo vệ kiểm soát rủi ro, mở khóa tạm thời online có hạn mức mỗi ngày.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_05','V1024','阮明',5,'医药费需要两千多元，临时限额只有一千，根本不够支付诊疗费用呢。','yī yào fèi xū yào liǎng qiān duō yuán， lín shí xiàn é zhǐ yǒu yī qiān， gēn běn bù gòu zhī fù zhěn liáo fèi yòng ne。','Tiền thuốc cần hơn hai nghìn tệ, hạn mức tạm thời chỉ có một nghìn, không đủ để thanh toán chi phí khám chữa bệnh đâu.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_06','V1024','客服',6,'线上解锁额度不足，需要你携带证件到线下网点办理全额解封。','xiàn shàng jiě suǒ é dù bù zú， xū yào nǐ xié dài zhèng jiàn dào xiàn xià wǎng diǎn bàn lǐ quán é jiě fēng。','Hạn mức mở khóa online không đủ, anh/chị cần mang giấy tờ tới điểm giao dịch trực tiếp để mở khóa toàn bộ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_07','V1024','阮明',7,'我现在在医院没法出门，有没有别的办法临时提高支付额度？','wǒ xiàn zài zài yī yuàn méi fǎ chū mén， yǒu méi yǒu bié de bàn fǎ lín shí tí gāo zhī fù é dù？','Em đang ở bệnh viện không ra ngoài được, có cách nào khác để tạm tăng hạn mức thanh toán không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_08','V1024','客服',8,'实在抱歉，风控规则无法线上调整，建议你更换其他银行卡缴费。','shí zài bào qiàn， fēng kòng guī zé wú fǎ xiàn shàng diào zhěng， jiàn yì nǐ gēng huàn qí tā yín háng kǎ jiǎo fèi。','Thật xin lỗi, quy định kiểm soát rủi ro không thể điều chỉnh online được, anh/chị nên dùng thẻ ngân hàng khác để thanh toán.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1025','SKC1','长途火车大面积晚点错过签证预约，向出入境窗口说明延误申请补受理',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1025','SIT1025','P1','that_bai_nhe','chinh_thuc',NULL,'政务大厅预约号严格分时段管控，交通延误仅可优先预约次日时段，无法直接当日插队办理业务。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_01','V1025','阮明',1,'吴主管您好，我原本今天预约办理签证续签，但是火车大面积晚点，错过了预约时段。','wú zhǔ guǎn nín hǎo， wǒ yuán běn jīn tiān yù yuē bàn lǐ qiān zhèng xù qiān， dàn shì huǒ chē dà miàn jī wǎn diǎn， cuò guò le yù yuē shí duàn。','Chào chị Ngô, tôi vốn đã đặt lịch hôm nay để gia hạn visa, nhưng do tàu hỏa bị chậm trên diện rộng nên tôi đã lỡ mất khung giờ hẹn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_02','V1025','吴主管',2,'先出示你的火车票晚点证明、预约回执，我先核实你的情况吧。','xiān chū shì nǐ de huǒ chē piào wǎn diǎn zhèng míng、 yù yuē huí zhí， wǒ xiān hé shí nǐ de qíng kuàng ba。','Trước tiên anh đưa tôi xem giấy xác nhận tàu chậm giờ và phiếu hẹn, để tôi kiểm tra tình hình của anh đã.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_03','V1025','阮明',3,'铁路官方短信晚点通知我带来了，路上延误三个小时，赶到大厅已经过号了啊。','tiě lù guān fāng duǎn xìn wǎn diǎn tōng zhī wǒ dài lái le， lù shàng yán wù sān gè xiǎo shí， gǎn dào dà tīng yǐ jīng guò hào le a。','Tôi có mang theo tin nhắn thông báo chậm giờ chính thức của đường sắt đây ạ, dọc đường bị trễ mất ba tiếng, đến được sảnh thì đã quá số rồi.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_04','V1025','吴主管',4,'每日预约名额系统固定，当日过号无特殊事由不能现场插队办理。','měi rì yù yuē míng é xì tǒng gù dìng， dāng rì guò hào wú tè shū shì yóu bù néng xiàn chǎng chā duì bàn lǐ。','Số lượng suất hẹn mỗi ngày là do hệ thống quy định cố định, nếu trong ngày quá số mà không có lý do đặc biệt thì không thể chen ngang xử lý tại chỗ được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_05','V1025','阮明',5,'我下周就要出境参加交换项目，错过今天只能再等一周预约，时间来不及。','wǒ xià zhōu jiù yào chū jìng cān jiā jiāo huàn xiàng mù， cuò guò jīn tiān zhǐ néng zài děng yī zhōu yù yuē， shí jiān lái bù jí。','Tuần sau tôi phải xuất cảnh để tham gia chương trình trao đổi rồi, nếu lỡ hôm nay thì phải chờ thêm một tuần mới đặt được lịch, thời gian sẽ không kịp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_06','V1025','吴主管',6,'火车晚点不属于法定加急事由，只能帮你优先预约明天最早时段号。','huǒ chē wǎn diǎn bù shǔ yú fǎ dìng jiā jí shì yóu， zhǐ néng bāng nǐ yōu xiān yù yuē míng tiān zuì zǎo shí duàn hào。','Tàu chậm giờ không thuộc diện lý do khẩn cấp theo quy định, tôi chỉ có thể ưu tiên giúp anh đặt suất sớm nhất vào ngày mai thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_07','V1025','阮明',7,'明天最早预约号是几点？我一定提前两小时到场，不会再迟到。','míng tiān zuì zǎo yù yuē hào shì jǐ diǎn？ wǒ yí dìng tí qián liǎng xiǎo shí dào chǎng， bú huì zài chí dào。','Suất sớm nhất ngày mai là mấy giờ ạ? Tôi nhất định sẽ đến trước hai tiếng, sẽ không trễ nữa đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_08','V1025','吴主管',8,'早上八点第一号，我给你做优先标记，明天直接凭身份证取号。','zǎo shàng bā diǎn dì yī hào， wǒ gěi nǐ zuò yōu xiān biāo jì， míng tiān zhí jiē píng shēn fèn zhèng qǔ hào。','Số đầu tiên là tám giờ sáng, tôi sẽ đánh dấu ưu tiên cho anh, ngày mai anh chỉ cần dùng CMND/CCCD để lấy số trực tiếp.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1101','SVL2','向国际学院提交校外兼职用工备案申请，等待学校审批许可',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1101','SIT1101','P1','twist','ban_chinh_thuc',NULL,'国内高校对留学生校外兼职实行备案制度，企业人事公章是备案审核硬性材料，缺少则无法通过审批。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_01','V1101','阮明',1,'张老师您好，我想提交校外兼职备案表，麻烦您帮忙审核一下吧。','zhāng lǎo shī nín hǎo， wǒ xiǎng tí jiāo xiào wài jiān zhí bèi àn biǎo， má fán nín bāng máng shěn hé yī xià ba。','Chào cô Trương, em muốn nộp mẫu đăng ký làm thêm bên ngoài trường, phiền cô kiểm tra giúp em ạ.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_02','V1101','张老师',2,'先把表格和企业用工证明给我，我看看材料齐不齐。','xiān bǎ biǎo gé hé qǐ yè yòng gōng zhèng míng gěi wǒ， wǒ kàn kàn cái liào qí bù qí。','Em đưa cô mẫu đơn với giấy xác nhận sử dụng lao động của công ty trước, để cô xem hồ sơ đã đủ chưa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_03','V1101','阮明',3,'表格我填好了，可公司那边只盖了业务章，没有人事专用章呢。','biǎo gé wǒ tián hǎo le， kě gōng sī nà biān zhǐ gài le yè wù zhāng， méi yǒu rén shì zhuān yòng zhāng ne。','Mẫu đơn em điền xong rồi, nhưng bên công ty chỉ đóng dấu nghiệp vụ thôi, không có dấu nhân sự riêng đâu ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_04','V1101','张老师',4,'备案必须人事公章，业务章学校这边是不认可的哦。','bèi àn bì xū rén shì gōng zhāng， yè wù zhāng xué xiào zhè biān shì bù rèn kě de ó。','Đăng ký bắt buộc phải có con dấu nhân sự, dấu nghiệp vụ thì nhà trường không công nhận đâu nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_05','V1101','阮明',5,'那我明天再去企业重新盖章，会不会耽误备案审批进度？','nà wǒ míng tiān zài qù qǐ yè chóng xīn gài zhāng， huì bú huì dān wù bèi àn shěn pī jìn dù？','Vậy để mai em quay lại công ty đóng dấu lại, như thế có làm chậm tiến độ xét duyệt đăng ký không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_06','V1101','张老师',6,'没事，你补齐公章后再来，审批一般三个工作日就能出结果。','méi shì， nǐ bǔ qí gōng zhāng hòu zài lái， shěn pī yì bān sān gè gōng zuò rì jiù néng chū jié guǒ。','Không sao đâu, em bổ sung đủ con dấu rồi quay lại là được, thường thì ba ngày làm việc là có kết quả xét duyệt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_07','V1101','阮明',7,'好嘞，辛苦老师啦，我明天一早就去公司补盖章。','hǎo lei， xīn kǔ lǎo shī la， wǒ míng tiān yī zǎo jiù qù gōng sī bǔ gài zhāng。','Dạ được ạ, cảm ơn cô nhiều nha, sáng mai em sẽ qua công ty đóng dấu bổ sung ngay.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1102','SVL2','携带企业实习证明前往出入境大厅办理居留许可实习加注',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1102','SIT1102','P1','suon_se','chinh_thuc',NULL,'外籍学生在中国实习、兼职必须完成居留许可实习加注，无证务工会被处罚甚至影响签证续签。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_01','V1102','阮明',1,'您好，我是外籍留学生，来办理实习加注，这是我的材料。','nín hǎo， wǒ shì wài jí liú xué shēng， lái bàn lǐ shí xí jiā zhù， zhè shì wǒ de cái liào。','Chào anh/chị, tôi là du học sinh nước ngoài, đến làm thủ tục ghi chú thực tập, đây là hồ sơ của tôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_02','V1102','小唐',2,'护照、实习协议、学校备案回执都带齐全了吗？','hù zhào、 shí xí xié yì、 xué xiào bèi àn huí zhí dōu dài qí quán le ma？','Anh đã mang đầy đủ hộ chiếu, thỏa thuận thực tập và phiếu xác nhận đăng ký của trường chưa?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_03','V1102','阮明',3,'全部都准备好了，我下周就要正式到公司上岗啦。','quán bù dōu zhǔn bèi hǎo le， wǒ xià zhōu jiù yào zhèng shì dào gōng sī shàng gǎng la。','Tôi chuẩn bị đầy đủ hết rồi, tuần sau tôi sẽ chính thức đến công ty nhận việc.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_04','V1102','小唐',4,'材料没问题，采集完人像，五个工作日就能办好加注。','cái liào méi wèn tí， cǎi jí wán rén xiàng， wǔ gè gōng zuò rì jiù néng bàn hǎo jiā zhù。','Hồ sơ không có vấn đề gì, sau khi lấy ảnh khuôn mặt xong, năm ngày làm việc là hoàn tất ghi chú.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_05','V1102','阮明',5,'办完加注之后，我就可以合法按照规定时长实习了对吧？','bàn wán jiā zhù zhī hòu， wǒ jiù kě yǐ hé fǎ àn zhào guī dìng shí cháng shí xí le duì ba？','Sau khi làm xong ghi chú, tôi có thể thực tập hợp pháp theo đúng thời hạn quy định phải không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_06','V1102','小唐',6,'没错，没有加注务工属于违规，千万不要提前上岗哦。','méi cuò， méi yǒu jiā zhù wù gōng shǔ yú wéi guī， qiān wàn bú yào tí qián shàng gǎng ó。','Đúng vậy, chưa có ghi chú mà đã đi làm là vi phạm quy định, nhất định đừng nhận việc trước thời hạn nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_07','V1102','阮明',7,'明白，我会等证件办好再去公司报到，麻烦您了。','míng bái， wǒ huì děng zhèng jiàn bàn hǎo zài qù gōng sī bào dào， má fán nín le。','Tôi hiểu rồi, tôi sẽ đợi làm xong giấy tờ rồi mới đến công ty trình diện, cảm ơn anh/chị đã giúp đỡ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1103','SVL2','多份兼职叠加工时超每周20小时，和雇主协商调整排班合规',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1103','SIT1103','P1','suon_se','ban_chinh_thuc',NULL,'国内政策限定留学生在校期间每周校外务工总时长不得超过20小时，所有雇主都需要配合遵守。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_01','V1103','阮明',1,'王店长，我算了下我两份兼职加起来每周工时超20小时，不符合留学生打工规定呢。','wáng diàn zhǎng， wǒ suàn le xià wǒ liǎng fèn jiān zhí jiā qǐ lái měi zhōu gōng shí chāo 20 xiǎo shí， bù fú hé liú xué shēng dǎ gōng guī dìng ne。','Anh Vương ơi, em tính thử rồi, tổng giờ làm của hai công việc bán thời gian của em mỗi tuần vượt quá 20 tiếng, không đúng với quy định làm thêm của du học sinh đâu ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_02','V1103','王店长',2,'还有这种限制吗？我之前不太清楚留学生的用工要求啊。','hái yǒu zhè zhǒng xiàn zhì ma？ wǒ zhī qián bù tài qīng chǔ liú xué shēng de yòng gōng yāo qiú a。','Còn có quy định như vậy nữa à? Trước giờ anh không rõ lắm về yêu cầu tuyển dụng đối với du học sinh.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_03','V1103','阮明',3,'教育局规定外籍学生每周校外工作不能超过二十小时，超时会有风险。','jiào yù jú guī dìng wài jí xué shēng měi zhōu xiào wài gōng zuò bù néng chāo guò èr shí xiǎo shí， chāo shí huì yǒu fēng xiǎn。','Sở giáo dục quy định sinh viên nước ngoài mỗi tuần làm việc bên ngoài trường không được quá hai mươi tiếng, làm quá giờ sẽ có rủi ro đấy ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_04','V1103','王店长',4,'原来是这样，那我把你这边排班每周减少两天，刚好控制工时。','yuán lái shì zhè yàng， nà wǒ bǎ nǐ zhè biān pái bān měi zhōu jiǎn shǎo liǎng tiān， gāng hǎo kòng zhì gōng shí。','Ra là vậy, vậy anh sẽ giảm bớt hai ngày trong lịch làm việc hàng tuần của em, như thế vừa khéo kiểm soát được số giờ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_05','V1103','阮明',5,'太感谢您理解啦，调整排班之后我两份工作都能安心做。','tài gǎn xiè nín lǐ jiě la， tiáo zhěng pái bān zhī hòu wǒ liǎng fèn gōng zuò dōu néng ān xīn zuò。','Em cảm ơn anh đã thông cảm nhiều lắm ạ, sau khi điều chỉnh lịch làm em có thể yên tâm làm cả hai công việc rồi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_06','V1103','王店长',6,'没事，合规最重要，下周我重新给你排新班次表。','méi shì， hé guī zuì zhòng yào， xià zhōu wǒ chóng xīn gěi nǐ pái xīn bān cì biǎo。','Không sao đâu, quan trọng nhất là làm đúng quy định, tuần sau anh sẽ sắp lại lịch ca mới cho em.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1104','SVL2','企业要求留学生无加注直接上岗，拒绝并解释合法打工规定',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1104','SIT1104','P1','that_bai_nhe','ban_chinh_thuc',NULL,'企业违规聘用未办理实习加注的外籍学生，市场监管与出入境可对企业处以高额罚款。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_01','V1104','阮明',1,'李姐，我现在还没办好出入境实习加注，暂时没办法上岗的。','lǐ jiě， wǒ xiàn zài hái méi bàn hǎo chū rù jìng shí xí jiā zhù， zàn shí méi bàn fǎ shàng gǎng de。','Chị Lý ơi, hiện giờ em vẫn chưa làm xong ghi chú thực tập ở cơ quan xuất nhập cảnh, nên tạm thời chưa thể nhận việc được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_02','V1104','李姐',2,'先过来上班嘛，加注后面抽空补办就行，不影响日常工作。','xiān guò lái shàng bān ma， jiā zhù hòu miàn chōu kòng bǔ bàn jiù xíng， bù yǐng xiǎng rì cháng gōng zuò。','Cứ đến làm trước đi mà, ghi chú thì sau này tranh thủ bổ sung là được, không ảnh hưởng gì đến công việc hàng ngày đâu.','AM09');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_03','V1104','阮明',3,'不行的，如果无证务工，不光我会受处罚，公司也要承担责任呢。','bù xíng de， rú guǒ wú zhèng wù gōng， bù guāng wǒ huì shòu chǔ fá， gōng sī yě yào chéng dān zé rèn ne。','Không được đâu ạ, nếu làm việc không có giấy phép thì không chỉ em bị xử phạt, mà công ty cũng phải chịu trách nhiệm đấy.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_04','V1104','李姐',4,'哪有这么严格，之前有外籍学生没办证也干了很久啦。','nǎ yǒu zhè me yán gé， zhī qián yǒu wài jí xué shēng méi bàn zhèng yě gàn le hěn jiǔ la。','Làm gì mà nghiêm ngặt vậy, trước đây có sinh viên nước ngoài không làm giấy tờ mà vẫn làm được lâu đấy thôi.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_05','V1104','阮明',5,'出入境会不定期核查企业用工，查到违规会罚款企业，我不能冒险。','chū rù jìng huì bù dìng qī hé chá qǐ yè yòng gōng， chá dào wéi guī huì fá kuǎn qǐ yè， wǒ bù néng mào xiǎn。','Cơ quan xuất nhập cảnh sẽ kiểm tra định kỳ việc sử dụng lao động của doanh nghiệp, nếu phát hiện vi phạm thì công ty sẽ bị phạt, em không thể mạo hiểm được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_06','V1104','李姐',6,'行吧，那等你办好加注再来入职，岗位先给你保留三天。','xíng ba， nà děng nǐ bàn hǎo jiā zhù zài lái rù zhí， gǎng wèi xiān gěi nǐ bǎo liú sān tiān。','Thôi được, vậy đợi em làm xong ghi chú rồi hẵng vào làm, vị trí này chị giữ cho em ba ngày trước đã.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_07','V1104','阮明',7,'麻烦您多等我几天，我会尽快办完证件过来报到。','má fán nín duō děng wǒ jǐ tiān， wǒ huì jǐn kuài bàn wán zhèng jiàn guò lái bào dào。','Phiền chị chờ em thêm mấy ngày, em sẽ làm giấy tờ xong sớm nhất rồi đến trình diện ngay ạ.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1105','SVL2','实习到期超过6个月，咨询出入境续办实习加注流程',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1105','SIT1105','P1','twist','chinh_thuc',NULL,'单次实习加注有效期一般不超过6个月，延长实习必须重新完成学校备案再办理加注续期。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_01','V1105','阮明',1,'您好，我的实习加注快到期，实习时长超过半年，该怎么续办呀？','nín hǎo， wǒ de shí xí jiā zhù kuài dào qī， shí xí shí cháng chāo guò bàn nián， gāi zěn me xù bàn ya？','Chào anh/chị, ghi chú thực tập của tôi sắp hết hạn, thời gian thực tập đã hơn nửa năm rồi, vậy tôi cần làm thủ tục gia hạn như thế nào ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_02','V1105','小周',2,'需要提供企业新出具的延长实习证明，还有学校最新备案回执。','xū yào tí gōng qǐ yè xīn chū jù de yán cháng shí xí zhèng míng， hái yǒu xué xiào zuì xīn bèi àn huí zhí。','Anh cần cung cấp giấy xác nhận gia hạn thực tập mới do công ty cấp, cùng với phiếu xác nhận đăng ký mới nhất của trường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_03','V1105','阮明',3,'学校备案回执上周刚过期，是不是要重新去学院申请一份？','xué xiào bèi àn huí zhí shàng zhōu gāng guò qī， shì bú shì yào chóng xīn qù xué yuàn shēn qǐng yī fèn？','Phiếu xác nhận đăng ký của trường mới hết hạn tuần trước, vậy có phải tôi cần quay lại khoa xin cấp lại một bản mới không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_04','V1105','小周',4,'是的，备案材料必须是当月有效，过期回执不能用来续办加注。','shì de， bèi àn cái liào bì xū shì dàng yuè yǒu xiào， guò qī huí zhí bù néng yòng lái xù bàn jiā zhù。','Đúng vậy, hồ sơ đăng ký phải còn hiệu lực trong tháng, phiếu đã hết hạn thì không thể dùng để gia hạn ghi chú được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_05','V1105','阮明',5,'那我今天先回学院重新办备案，明天再来窗口提交材料可以吗？','nà wǒ jīn tiān xiān huí xué yuàn chóng xīn bàn bèi àn， míng tiān zài lái chuāng kǒu tí jiāo cái liào kě yǐ ma？','Vậy hôm nay tôi về khoa làm lại thủ tục đăng ký trước, mai quay lại quầy nộp hồ sơ được không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_06','V1105','小周',6,'没问题，材料齐全当天就能受理，记得带白底证件照两张。','méi wèn tí， cái liào qí quán dàng tiān jiù néng shòu lǐ， jì de dài bái dǐ zhèng jiàn zhào liǎng zhāng。','Không vấn đề gì, hồ sơ đầy đủ thì ngay trong ngày là được tiếp nhận, nhớ mang theo hai tấm ảnh thẻ nền trắng nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_07','V1105','阮明',7,'好的，我记下来所有要求，不会再漏带材料啦。','hǎo de， wǒ jì xià lái suǒ yǒu yāo qiú， bú huì zài lòu dài cái liào la。','Vâng, tôi sẽ ghi lại đầy đủ các yêu cầu, sẽ không quên mang thiếu giấy tờ nữa đâu.','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1106','SVL2','更换兼职单位，重新向学校与出入境提交用工备案材料',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1106','SIT1106','P1','suon_se','ban_chinh_thuc',NULL,'留学生每更换一家兼职/实习单位，都要单独完成学校备案，不能沿用旧单位备案证明。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_01','V1106','阮明',1,'张老师，我换了一份新兼职，需要重新提交备案材料对吧？','zhāng lǎo shī， wǒ huàn le yī fèn xīn jiān zhí， xū yào chóng xīn tí jiāo bèi àn cái liào duì ba？','Cô Trương ơi, em vừa đổi sang một công việc làm thêm mới, cần nộp lại hồ sơ đăng ký đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_02','V1106','张老师',2,'没错，更换用工单位必须重新走备案流程，旧备案自动失效。','méi cuò， gēng huàn yòng gōng dān wèi bì xū chóng xīn zǒu bèi àn liú chéng， jiù bèi àn zì dòng shī xiào。','Đúng vậy, khi đổi nơi làm việc thì bắt buộc phải làm lại quy trình đăng ký, hồ sơ cũ sẽ tự động hết hiệu lực.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_03','V1106','阮明',3,'新公司的用工协议、营业执照复印件我都打印带来了。','xīn gōng sī de yòng gōng xié yì、 yíng yè zhí zhào fù yìn jiàn wǒ dōu dǎ yìn dài lái le。','Thỏa thuận lao động và bản photo giấy phép kinh doanh của công ty mới em đều in ra mang theo hết rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_04','V1106','张老师',4,'材料齐全，我今天录入系统，三天后给你出新备案回执。','cái liào qí quán， wǒ jīn tiān lù rù xì tǒng， sān tiān hòu gěi nǐ chū xīn bèi àn huí zhí。','Hồ sơ đầy đủ rồi, hôm nay cô sẽ nhập vào hệ thống, ba ngày nữa sẽ cấp phiếu xác nhận đăng ký mới cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_05','V1106','阮明',5,'拿到回执我就去出入境更新实习加注，不会耽误上班。','ná dào huí zhí wǒ jiù qù chū rù jìng gēng xīn shí xí jiā zhù， bú huì dān wù shàng bān。','Lấy được phiếu xác nhận rồi em sẽ đi cập nhật ghi chú thực tập ở cơ quan xuất nhập cảnh ngay, sẽ không làm chậm việc đi làm đâu ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_06','V1106','张老师',6,'记得旧兼职单位那边也要办好离职交接，避免两边工时叠加超标。','jì de jiù jiān zhí dān wèi nà biān yě yào bàn hǎo lí zhí jiāo jiē， bì miǎn liǎng biān gōng shí dié jiā chāo biāo。','Nhớ là bên công ty làm thêm cũ cũng phải làm xong thủ tục bàn giao thôi việc, để tránh giờ làm hai bên cộng dồn vượt mức quy định.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_07','V1106','阮明',7,'我已经和上一家店长沟通好离职，您放心吧。','wǒ yǐ jīng hé shàng yī jiā diàn zhǎng gōu tōng hǎo lí zhí， nín fàng xīn ba。','Em đã trao đổi xong với quản lý cửa hàng cũ về việc nghỉ việc rồi ạ, cô cứ yên tâm.','AM07');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1107','SVL2','参加企业新人岗前安全培训，记录不懂的工作流程提问主管',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1107','SIT1107','P1','suon_se','ban_chinh_thuc',NULL,'国内服务业、制造业上岗前强制安全培训，员工主动提问操作细节会被认为认真负责，雇主很认可。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_01','V1107','阮明',1,'陈主管，刚刚安全培训里的设备操作步骤，我还有两处没听懂呢。','chén zhǔ guǎn， gāng gāng ān quán péi xùn lǐ de shè bèi cāo zuò bù zhòu， wǒ hái yǒu liǎng chù méi tīng dǒng ne。','Anh Trần ơi, phần các bước thao tác thiết bị trong buổi tập huấn an toàn vừa rồi em còn hai chỗ chưa hiểu rõ ạ.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_02','V1107','陈主管',2,'哪一部分不清楚，你直接说，我再给你演示一遍。','nǎ yī bù fèn bù qīng chǔ， nǐ zhí jiē shuō， wǒ zài gěi nǐ yǎn shì yī biàn。','Chỗ nào chưa rõ thì em cứ nói thẳng ra, anh sẽ làm mẫu lại cho em xem một lần nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_03','V1107','阮明',3,'就是清洁机器的断电流程，培训讲得有点快，我没记完整。','jiù shì qīng jié jī qì de duàn diàn liú chéng， péi xùn jiǎng dé yǒu diǎn kuài， wǒ méi jì wán zhěng。','Là quy trình ngắt điện khi vệ sinh máy đó ạ, lúc tập huấn nói hơi nhanh nên em ghi nhớ chưa đầy đủ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_04','V1107','陈主管',4,'我带你到设备旁实操一遍，记住维修清洁必须先断总电源。','wǒ dài nǐ dào shè bèi páng shí cāo yī biàn， jì zhù wéi xiū qīng jié bì xū xiān duàn zǒng diàn yuán。','Anh sẽ dẫn em ra chỗ máy để thực hành lại một lần, nhớ là khi bảo trì vệ sinh thì bắt buộc phải ngắt nguồn điện tổng trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_05','V1107','阮明',5,'原来是这样，还好主动问清楚，不然操作失误会有安全隐患。','yuán lái shì zhè yàng， hái hǎo zhǔ dòng wèn qīng chǔ， bù rán cāo zuò shī wù huì yǒu ān quán yǐn huàn。','Ra là vậy, may mà em chủ động hỏi cho rõ, không thì thao tác sai sẽ có nguy cơ mất an toàn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_06','V1107','陈主管',6,'有不懂的随时来问，千万不要自己随意操作机器哦。','yǒu bù dǒng de suí shí lái wèn， qiān wàn bú yào zì jǐ suí yì cāo zuò jī qì ó。','Có gì không hiểu thì cứ đến hỏi bất cứ lúc nào, tuyệt đối đừng tự ý thao tác máy móc một mình nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_07','V1107','阮明',7,'好的，我会把所有注意事项全部记在笔记本上。','hǎo de， wǒ huì bǎ suǒ yǒu zhù yì shì xiàng quán bù jì zài bǐ jì běn shàng。','Vâng ạ, em sẽ ghi hết tất cả các lưu ý vào sổ tay.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1108','SVL2','入职要求提供外国人健康证，咨询办理地点与所需材料',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1108','SIT1108','P1','twist','ban_chinh_thuc',NULL,'外籍从业人员需办理专属外籍健康证明，普通国内健康证无法用于留学生兼职入职。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_01','V1108','阮明',1,'李姐，入职要外国人专用健康证，我不清楚去哪里办理呀？','lǐ jiě， rù zhí yào wài guó rén zhuān yòng jiàn kāng zhèng， wǒ bù qīng chǔ qù nǎ lǐ bàn lǐ ya？','Chị Lý ơi, vào làm cần giấy khám sức khỏe dành riêng cho người nước ngoài, em không rõ đi đâu để làm đây ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_02','V1108','李姐',2,'去市国际旅行卫生保健中心，带上护照和一寸照片就行。','qù shì guó jì lǚ xíng wèi shēng bǎo jiàn zhōng xīn， dài shàng hù zhào hé yī cùn zhào piān jiù xíng。','Đến trung tâm kiểm dịch y tế quốc tế của thành phố, mang theo hộ chiếu với ảnh 1 inch là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_03','V1108','阮明',3,'我今天只有护照，照片落在宿舍，明天过去办理来得及吗？','wǒ jīn tiān zhǐ yǒu hù zhào， zhào piān luò zài sù shè， míng tiān guò qù bàn lǐ lái de jí ma？','Hôm nay em chỉ có hộ chiếu thôi, ảnh để quên ở ký túc xá rồi, mai qua làm có kịp không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_04','V1108','李姐',4,'可以，体检当天就能拿临时回执，正式证件三天后领取。','kě yǐ， tǐ jiǎn dàng tiān jiù néng ná lín shí huí zhí， zhèng shì zhèng jiàn sān tiān hòu lǐng qǔ。','Được, hôm khám xong là lấy được biên nhận tạm ngay, còn giấy chính thức thì ba ngày sau lấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_05','V1108','阮明',5,'体检需要空腹吗？我怕早上吃了东西白跑一趟。','tǐ jiǎn xū yào kōng fù ma？ wǒ pà zǎo shàng chī le dōng xī bái pǎo yī tàng。','Khám có cần nhịn ăn không ạ? Em sợ sáng mà ăn gì vào thì lại phải đi lại lần nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_06','V1108','李姐',6,'早上空腹抽血，你明天早点过去，人会少很多。','zǎo shàng kōng fù chōu xuè， nǐ míng tiān zǎo diǎn guò qù， rén huì shǎo hěn duō。','Sáng nhịn ăn để lấy máu, em đi sớm một chút vào ngày mai, người sẽ vắng hơn nhiều đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_07','V1108','阮明',7,'多谢提醒，我明天一早空腹过去体检。','duō xiè tí xǐng， wǒ míng tiān yī zǎo kōng fù guò qù tǐ jiǎn。','Cảm ơn chị nhắc nhé, mai em sẽ nhịn ăn đi khám sớm.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1109','SVL2','询问实习/兼职是否提供工作餐、交通补贴、全勤奖励',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1109','SIT1109','P1','suon_se','tuy_y',NULL,'餐饮、零售类兼职普遍设有员工餐、交通补贴、全勤奖，面试入职主动询问福利属于正常沟通。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_01','V1109','阮明',1,'店长，我想问下咱们兼职有没有工作餐和交通补贴呀？','diàn zhǎng， wǒ xiǎng wèn xià zán men jiān zhí yǒu méi yǒu gōng zuò cān hé jiāo tōng bǔ tiē ya？','Quản lý ơi, em muốn hỏi làm bán thời gian ở đây có cơm nhân viên với trợ cấp đi lại không ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_02','V1109','王店长',2,'工作日值班提供免费员工餐，交通补贴每月五十块呢。','gōng zuò rì zhí bān tí gōng miǎn fèi yuán gōng cān， jiāo tōng bǔ tiē měi yuè wǔ shí kuài ne。','Ngày làm trực thì có cơm miễn phí cho nhân viên, trợ cấp đi lại mỗi tháng năm chục nghìn nhé.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_03','V1109','阮明',3,'那全勤奖励是什么标准，每月不迟到就能拿到吗？','nà quán qín jiǎng lì shì shén me biāo zhǔn， měi yuè bù chí dào jiù néng ná dào ma？','Vậy thưởng chuyên cần tính theo tiêu chuẩn nào, tháng không đi trễ là được nhận luôn hả?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_04','V1109','王店长',4,'当月无迟到早退、不临时请假，月底多两百元全勤奖。','dàng yuè wú chí dào zǎo tuì、 bù lín shí qǐng jià， yuè dǐ duō liǎng bǎi yuán quán qín jiǎng。','Tháng đó không đi trễ về sớm, không xin nghỉ đột xuất, cuối tháng được thêm hai trăm tệ thưởng chuyên cần.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_05','V1109','阮明',5,'福利还挺不错的，我一定会尽量全勤上班。','fú lì hái tǐng bù cuò de， wǒ yí dìng huì jǐn liàng quán qín shàng bān。','Phúc lợi cũng khá ổn đó chứ, em nhất định sẽ cố gắng đi làm đều đặn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_06','V1109','王店长',6,'好好干，后续表现好还能给你调整排班和时薪。','hǎo hǎo gàn， hòu xù biǎo xiàn hǎo hái néng gěi nǐ tiáo zhěng pái bān hé shí xīn。','Cố gắng làm tốt vào, sau này làm tốt còn được điều chỉnh ca làm với lương giờ nữa đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_07','V1109','阮明',7,'好嘞，麻烦店长啦！','hǎo lei， má fán diàn zhǎng la！','Dạ được, phiền quản lý nhiều nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1110','SVL2','学习公司考勤打卡系统，忘记打卡找人事补录考勤记录',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1110','SIT1110','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内企业考勤补卡普遍需要主管签字佐证，且每月有固定补卡次数上限，超出会扣除全勤奖金。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_01','V1110','阮明',1,'小吴，我今早上班忘记打卡，能不能帮忙补录一下考勤？','xiǎo wú， wǒ jīn zǎo shàng bān wàng jì dǎ kǎ， néng bù néng bāng máng bǔ lù yī xià kǎo qín？','Tiểu Ngô ơi, sáng nay em đi làm quên chấm công, giúp em bổ sung lại được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_02','V1110','小吴',2,'补打卡需要提交书面说明，还要你的当班主管签字确认。','bǔ dǎ kǎ xū yào tí jiāo shū miàn shuō míng， hái yào nǐ dí dàng bān zhǔ guǎn qiān zì què rèn。','Bổ sung chấm công thì cần nộp bản giải trình bằng văn bản, còn phải có chữ ký xác nhận của quản lý ca em nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_03','V1110','阮明',3,'我现在去找主管签字，签完马上拿过来给你行吗？','wǒ xiàn zài qù zhǎo zhǔ guǎn qiān zì， qiān wán mǎ shàng ná guò lái gěi nǐ xíng ma？','Giờ em đi tìm quản lý ký xong mang qua đưa chị luôn được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_04','V1110','小吴',4,'今天下班前提交都可以，超过当日就没办法补录啦。','jīn tiān xià bān qián tí jiāo dōu kě yǐ， chāo guò dāng rì jiù méi bàn fǎ bǔ lù la。','Hôm nay nộp trước giờ tan làm là được, qua ngày là không thể bổ sung được nữa đâu.','AM02');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_05','V1110','阮明',5,'原来是有时间限制，还好我及时过来咨询，差点错过。','yuán lái shì yǒu shí jiān xiàn zhì， hái hǎo wǒ jí shí guò lái zī xún， chà diǎn cuò guò。','Ra là có giới hạn thời gian, may mà em đến hỏi kịp lúc, suýt nữa lỡ mất.',NULL);
